T+DjOQA=
NEXUS_BIN_GZ_B64
  verify_file "$dest" "$BINARY_SHA256" || { rm -f "$dest"; return 1; }
  chmod 0755 "$dest"
}
valid_config() {
  run_root "[ -s '$1' ] && grep -q '^version=' '$1' 2>/dev/null && grep -Eq '^(boxes|skeleton|fps_cap|theme)=' '$1' 2>/dev/null"
}
prepare_runtime() {
  run_root "[ ! -L '$RUNTIME' ] && mkdir -p '$RUNTIME'" || return 1
  owner="$(run_root "stat -c %u '$RUNTIME'" 2>/dev/null)"
  [ "$owner" = 0 ] || { echo "Update directory owner mismatch" >&2; return 1; }
  run_root "chmod 0700 '$RUNTIME'" || return 1
}
prepare_config() {
  prepare_runtime || return 1
  if valid_config "$CONFIG"; then
    echo "Using existing config: $CONFIG"
    run_root "sed -i 's/^language=0/language=1/' '$CONFIG' 2>/dev/null || true"
    return 0
  fi
  echo "No existing NEXUS.ini found; defaults will be used."
}

sanitize_variant_config() {
  if [ "$VARIANT" = "official" ]; then
    run_root "if [ -f '$CONFIG' ]; then sed -i '/^tracking_/d' '$CONFIG'; fi" || return 1
  fi
}
# Quote the actual launch path and every argument when crossing the su boundary.
shell_quote() {
  printf "'%s'" "$(printf '%s' "$1" | sed "s/'/'\\\\''/g")"
}
launch_installed() {
  LAUNCHER_PATH="$(readlink -f "$0")"
  [ -n "$LAUNCHER_PATH" ] && [ -f "$LAUNCHER_PATH" ] || { echo "Cannot resolve original launcher path" >&2; return 1; }
  launcher_q="$(shell_quote "$LAUNCHER_PATH")"
  EXTRA=""
  for arg in "$@"; do EXTRA="$EXTRA $(shell_quote "$arg")"; done
  prepare_runtime || return 1
  # One-time migration from 2.8.9's independent installed-ELF layout.
  # A script transaction always has pending.launcher; leave that recovery to runner.
  run_root "if [ ! -f '$RUNTIME/pending.launcher' ]; then rm -f '$RUNTIME/pending.version' '$RUNTIME/previous.elf' '$RUNTIME/recovered.once'; fi" || return 1
  work="$(mktemp -d /data/local/tmp/.NEXUS-XXXXXX)" || return 1
  printf '%s' '' | base64 -d > "$work/runner.sh" || { rm -rf "$work"; return 1; }
  run_root "cp '$work/runner.sh' '$RUNTIME/runner.new' && chmod 0700 '$RUNTIME/runner.new' && mv -f '$RUNTIME/runner.new' '$RUNTIME/runner.sh' && rm -f '$RUNTIME/stop.request'" || { rm -rf "$work"; return 1; }
  rm -rf "$work"
  run_root "HX_LAUNCHER_PATH=$launcher_q nohup sh '$RUNTIME/runner.sh' '$RUNTIME' '$CONFIG' $EXTRA </dev/null >/dev/null 2>&1 &" || return 1
  sleep 2
  pid="$(run_root "pidof NEXUS" 2>/dev/null | awk '{print $1}')"
  [ -n "$pid" ] || { echo "Startup failed; see $RUNTIME/launcher.log and runtime.log" >&2; return 1; }
  echo "Launcher: $LAUNCHER_PATH (cloud updates replace its embedded ELF; temporary ELF is removed after start)"
}
stop_running() {
  run_root "if [ -d '$RUNTIME' ] && [ ! -L '$RUNTIME' ]; then touch '$RUNTIME/stop.request'; fi" || return 1
  run_root "pkill -TERM -x NEXUS >/dev/null 2>&1 || true"
  wait_count=0
  while run_root "pidof NEXUS >/dev/null 2>&1"; do
    wait_count=$((wait_count + 1))
    [ "$wait_count" -lt 15 ] || { echo "Old overlay still running; abort instead of racing hooks" >&2; return 1; }
    sleep 1
  done
  sleep 2 # Let the old supervisor observe stop.request before removing it.
}
launch_detached() {
  stop_running || return 1
  prepare_config && sanitize_variant_config || return 1
  launch_installed || { echo "NEXUS exited" >&2; return 1; }
  pid="$(run_root "pidof NEXUS" 2>/dev/null | awk '{print $1}')"
  echo "NEXUS installed UI started (PID $pid, config $CONFIG)."
}
usage() { echo "NEXUS-ANDROID | --verify | --stop | --server URL --update-server URL --config FILE --font TTF --lang zh|en --probe"; }
# Internal supervisor entry: decode only, without stop/start side effects.
if [ "$1" = "--extract-runtime" ]; then
  [ $# -eq 2 ] || exit 2
  decode_binary_to "$2"
  exit $?
fi
if [ $# -eq 0 ]; then launch_detached; exit $?; fi
case "$1" in
  --help) usage ;;
  --stop) stop_running ;;
  --verify)
    tmp="$(mktemp /data/local/tmp/.NEXUS-XXXXXX)" || exit 1
    decode_binary_to "$tmp" && echo "verified binary=$BINARY_SHA256 source_archive=$SOURCE_ARCHIVE_SHA256"
    rc=$?; rm -f "$tmp"; exit $rc ;;
  --server|--update-server|--config|--font|--lang|--probe) stop_running && prepare_config && sanitize_variant_config && launch_installed "$@"; exit $? ;;
  *) usage; exit 2 ;;
esac
